import sys
from functools import lru_cache

total_balls = 100

@lru_cache(maxsize=None)
def dp(platform, next_ball):
    if next_ball > total_balls and len(platform) == 0:
        return [0.0]*total_balls
    res = [0.0]*total_balls
    n = len(platform)
    if n == 0:
        return res
    for pos in range(n):
        prob = 1.0 / n
        res[platform[pos]-1] += prob
        new_platform = []
        new_next = next_ball
        if pos == 0:
            if n > 1:
                new_platform = platform[1:]
            if new_next <= total_balls:
                new_platform.append(new_next)
                new_next += 1
        elif pos == 1:
            if n == 3:
                new_platform = [platform[2]]
                for _ in range(2):
                    if new_next <= total_balls:
                        new_platform.append(new_next)
                        new_next +=1
        elif pos == 2:
            if n ==3:
                new_platform = [platform[1]]
                for _ in range(2):
                    if new_next <= total_balls:
                        new_platform.append(new_next)
                        new_next +=1
        sub_res = dp(tuple(new_platform), new_next)
        for i in range(total_balls):
            res[i] += prob * sub_res[i]
    return res

initial_platform = (1, 2, 3)
probs = dp(initial_platform, 4)
max_prob = max(probs)
max_ball = probs.index(max_prob) + 1
print(f"Max probability ball: {max_ball}, probability: {max_prob}")
print(f"All probs: {probs}")

import sys
from functools import lru_cache

total_balls = 100

@lru_cache(maxsize=None)
def dp(platform, next_ball):
    probs = [0.0] * (total_balls + 1)
    if next_ball > total_balls and all(b == 0 for b in platform):
        return probs
    for pos in range(3):
        if platform[pos] == 0:
            continue
        ball = platform[pos]
        p = 1/3
        probs[ball] += p
        new_platform = list(platform)
        new_next = next_ball
        if pos == 0:
            new_platform[0] = new_platform[1]
            new_platform[1] = new_platform[2]
            if new_next <= total_balls:
                new_platform[2] = new_next
                new_next += 1
            else:
                new_platform[2] = 0
        elif pos == 1:
            if new_next + 1 <= total_balls:
                new_platform = [new_platform[2], new_next, new_next + 1]
                new_next += 2
            elif new_next <= total_balls:
                new_platform = [new_platform[2], new_next, 0]
                new_next += 1
            else:
                new_platform = [new_platform[2], 0, 0]
        elif pos == 2:
            if new_next + 1 <= total_balls:
                new_platform = [new_platform[1], new_next, new_next + 1]
                new_next += 2
            elif new_next <= total_balls:
                new_platform = [new_platform[1], new_next, 0]
                new_next += 1
            else:
                new_platform = [new_platform[1], 0, 0]
        rest_probs = dp(tuple(new_platform), new_next)
        for i in range(1, total_balls + 1):
            probs[i] += p * rest_probs[i]
    return probs

initial_platform = (1, 2, 3)
probs = dp(initial_platform, 4)
max_prob = -1
max_ball = 1
for i in range(1, total_balls + 1):
    if probs[i] > max_prob:
        max_prob = probs[i]
        max_ball = i
